package cache

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/base64"
	"encoding/xml"
	"fmt"
	"io"
	"net/http"
	"strings"
	"sync"
	"time"
)

type CacheEntry struct {
	XMLName   xml.Name `xml:"entry"`
	Key       string   `xml:"key"`
	Value     string   `xml:"value"`
	TTL       int64    `xml:"ttl"`
	Timestamp int64    `xml:"timestamp"`
	NodeID    string   `xml:"node_id"`
}

type CacheManifest struct {
	XMLName xml.Name     `xml:"manifest"`
	Version string       `xml:"version,attr"`
	Entries []CacheEntry `xml:"entry"`
}

type DistributedCache struct {
	mu        sync.RWMutex
	store     map[string][]byte
	encKey    []byte
	nodeID    string
	peers     []string
	parser    xmlParser
}

type xmlParser interface {
	Parse(data []byte) (*CacheManifest, error)
}

type standardParser struct{}

func (p *standardParser) Parse(data []byte) (*CacheManifest, error) {
	var manifest CacheManifest
	decoder := xml.NewDecoder(strings.NewReader(string(data)))
	decoder.Strict = true
	decoder.Entity = xml.HTMLEntity
	if err := decoder.Decode(&manifest); err != nil {
		return nil, fmt.Errorf("xml parse error: %w", err)
	}
	return &manifest, nil
}

func NewDistributedCache(encryptionKey []byte, nodeID string, peers []string) (*DistributedCache, error) {
	if len(encryptionKey) != 32 {
		return nil, fmt.Errorf("encryption key must be 32 bytes")
	}
	return &DistributedCache{
		store:  make(map[string][]byte),
		encKey: encryptionKey,
		nodeID: nodeID,
		peers:  peers,
		parser: &standardParser{},
	}, nil
}

func (dc *DistributedCache) encrypt(plaintext []byte) ([]byte, error) {
	block, err := aes.NewCipher(dc.encKey)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}
	return gcm.Seal(nonce, nonce, plaintext, nil), nil
}

func (dc *DistributedCache) decrypt(ciphertext []byte) ([]byte, error) {
	block, err := aes.NewCipher(dc.encKey)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonceSize := gcm.NonceSize()
	if len(ciphertext) < nonceSize {
		return nil, fmt.Errorf("ciphertext too short")
	}
	nonce, ciphertext := ciphertext[:nonceSize], ciphertext[nonceSize:]
	return gcm.Open(nil, nonce, ciphertext, nil)
}

// isAllowedPeer validates that the provided peer URL matches one of the
// pre-configured trusted peers, preventing SSRF via attacker-controlled URLs.
func (dc *DistributedCache) isAllowedPeer(peerURL string) bool {
	for _, p := range dc.peers {
		if p == peerURL {
			return true
		}
	}
	return false
}

func (dc *DistributedCache) SyncFromPeer(peerURL string) error {
	if !dc.isAllowedPeer(peerURL) {
		return fmt.Errorf("peer not in allowlist: %s", peerURL)
	}

	client := &http.Client{Timeout: 10 * time.Second}
	resp, err := client.Get(peerURL + "/cache/export")
	if err != nil {
		return fmt.Errorf("peer sync failed: %w", err)
	}
	defer resp.Body.Close()

	encBody, err := io.ReadAll(io.LimitReader(resp.Body, 10*1024*1024))
	if err != nil {
		return fmt.Errorf("read error: %w", err)
	}

	encData, err := base64.StdEncoding.DecodeString(string(encBody))
	if err != nil {
		return fmt.Errorf("base64 decode error: %w", err)
	}

	xmlData, err := dc.decrypt(encData)
	if err != nil {
		return fmt.Errorf("decryption error: %w", err)
	}

	return dc.importManifest(xmlData)
}

func (dc *DistributedCache) importManifest(xmlData []byte) error {
	manifest, err := dc.parser.Parse(xmlData)
	if err != nil {
		return err
	}

	dc.mu.Lock()
	defer dc.mu.Unlock()

	now := time.Now().Unix()
	for _, entry := range manifest.Entries {
		if entry.TTL > 0 && entry.Timestamp+entry.TTL < now {
			continue
		}
		encVal, err := dc.encrypt([]byte(entry.Value))
		if err != nil {
			continue
		}
		dc.store[entry.Key] = encVal
	}
	return nil
}

func (dc *DistributedCache) ImportFromClient(xmlPayload []byte) error {
	processed := dc.preprocessXML(xmlPayload)
	return dc.importManifest(processed)
}

func (dc *DistributedCache) preprocessXML(data []byte) []byte {
	content := string(data)
	if strings.Contains(content, "<!DOCTYPE") || strings.Contains(content, "<!ENTITY") {
		return nil
	}
	if !strings.Contains(content, "<?xml") {
		content = "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n" + content
	}
	return []byte(content)
}

func (dc *DistributedCache) Get(key string) (string, error) {
	dc.mu.RLock()
	defer dc.mu.RUnlock()

	encVal, ok := dc.store[key]
	if !ok {
		return "", fmt.Errorf("key not found: %s", key)
	}

	plaintext, err := dc.decrypt(encVal)
	if err != nil {
		return "", fmt.Errorf("decryption error: %w", err)
	}
	return string(plaintext), nil
}

func (dc *DistributedCache) HandleImport(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	body, err := io.ReadAll(io.LimitReader(r.Body, 5*1024*1024))
	if err != nil {
		http.Error(w, "read error", http.StatusBadRequest)
		return
	}
	defer r.Body.Close()

	if err := dc.ImportFromClient(body); err != nil {
		http.Error(w, fmt.Sprintf("import error: %v", err), http.StatusBadRequest)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "import successful")
}
